// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(uint256 initialSupply, uint256 burnAmount) public {
        vm.assume(initialSupply > 0 && burnAmount > 0 && burnAmount <= initialSupply);
        c = new ERCDDAToken(initialSupply, "", "");
        uint256 totalBefore = c.totalSupply();
        vm.prank(c.owner());
        c.burn(burnAmount);
        uint256 totalAfter = c.totalSupply();
        assertTrue(totalAfter < totalBefore);
    }
}
